package EX18.EX89;

import java.sql.Connection;
import java.sql.Statement;

public class Main {
    public static void main(String[] args) throws Exception {
        try (Connection conn = ConnectionFactory.getConnection();
             Statement st = conn.createStatement()) {
            st.execute("CREATE TABLE clientes (" +
                    "id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, " +
                    "nome VARCHAR(120) NOT NULL, " +
                    "cpf VARCHAR(14) NOT NULL UNIQUE, " +
                    "email VARCHAR(150) NOT NULL)");
        }

        ClienteDAO dao = new ClienteDAOImpl();
        ClienteService service = new ClienteService(dao);

        Cliente ok = new Cliente("João", "123.456.789-00", "joao@email.com");
        service.cadastrarCliente(ok);
        System.out.println("Cadastrado: " + ok);

        tentar(service, new Cliente("Ana", "111.111.111-11", ""));
        tentar(service, new Cliente("Pedro", "123.456.789-00", "pedro@email.com"));
    }

    private static void tentar(ClienteService service, Cliente c) {
        try {
            service.cadastrarCliente(c);
            System.out.println("Cadastrado: " + c);
        } catch (RegraDeNegocioException e) {
            System.out.println("Rejeitado: " + e.getMessage());
        }
    }
}